// ── Valida X-Hub-Signature-256 ────────────────────────────────────────────
// Meta firma el cuerpo CRUDO con HMAC-SHA256 usando el App Secret.
// n8n bloquea el módulo 'crypto', así que va en JS puro (mismo núcleo
// SHA-256 que ya usamos en "Preparar evento Meta" para el CAPI).
//
// Se valida sobre $binary.data (los bytes tal cual llegaron), NUNCA sobre
// JSON.stringify($json.body): al reserializar, emojis y tildes cambian de
// codificación y la firma dejaría de cuadrar en mensajes reales.

// El secreto NO vive dentro del nodo: llega del entorno de n8n (fichero wa.env).
const APP_SECRET = $env.WA_APP_SECRET || '';

function sha256Bytes(input){
  function rotr(n,x){return (x>>>n)|(x<<(32-n));}
  function ch(x,y,z){return (x&y)^(~x&z);}
  function maj(x,y,z){return (x&y)^(x&z)^(y&z);}
  function s0(x){return rotr(2,x)^rotr(13,x)^rotr(22,x);}
  function s1(x){return rotr(6,x)^rotr(11,x)^rotr(25,x);}
  function g0(x){return rotr(7,x)^rotr(18,x)^(x>>>3);}
  function g1(x){return rotr(17,x)^rotr(19,x)^(x>>>10);}
  const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const bytes=input.slice();
  const bitLen=bytes.length*8;
  bytes.push(0x80);
  while(bytes.length%64!==56) bytes.push(0);
  for(let i=7;i>=0;i--) bytes.push(Math.floor(bitLen/Math.pow(2,i*8))&0xff);
  for(let b=0;b<bytes.length;b+=64){
    const w=new Array(64);
    for(let i=0;i<16;i++) w[i]=(bytes[b+i*4]<<24)|(bytes[b+i*4+1]<<16)|(bytes[b+i*4+2]<<8)|bytes[b+i*4+3];
    for(let i=16;i<64;i++) w[i]=(g1(w[i-2])+w[i-7]+g0(w[i-15])+w[i-16])|0;
    let a=H[0],bb=H[1],cc=H[2],dd=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
    for(let i=0;i<64;i++){
      const t1=(h+s1(e)+ch(e,f,g)+K[i]+w[i])|0;
      const t2=(s0(a)+maj(a,bb,cc))|0;
      h=g;g=f;f=e;e=(dd+t1)|0;dd=cc;cc=bb;bb=a;a=(t1+t2)|0;
    }
    H=[(H[0]+a)|0,(H[1]+bb)|0,(H[2]+cc)|0,(H[3]+dd)|0,(H[4]+e)|0,(H[5]+f)|0,(H[6]+g)|0,(H[7]+h)|0];
  }
  return H.map(x=>((x>>>0).toString(16).padStart(8,'0'))).join('');
}
function utf8Bytes(s){const o=[];for(const c of unescape(encodeURIComponent(String(s)))) o.push(c.charCodeAt(0));return o;}
function hexToBytes(h){const o=[];for(let i=0;i<h.length;i+=2) o.push(parseInt(h.substr(i,2),16));return o;}
function b64ToBytes(str){
  const T='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const s=String(str).replace(/[^A-Za-z0-9+/]/g,'');
  const o=[];
  for(let i=0;i<s.length;i+=4){
    const c0=T.indexOf(s[i]), c1=T.indexOf(s[i+1]);
    const c2=(i+2<s.length)?T.indexOf(s[i+2]):-1;
    const c3=(i+3<s.length)?T.indexOf(s[i+3]):-1;
    o.push(((c0<<2)|(c1>>4))&255);
    if(c2>=0) o.push(((c1<<4)|(c2>>2))&255);
    if(c3>=0) o.push(((c2<<6)|c3)&255);
  }
  return o;
}
function hmacSha256(keyBytes,msgBytes){
  let k=keyBytes.slice();
  if(k.length>64) k=hexToBytes(sha256Bytes(k));
  while(k.length<64) k.push(0);
  const ip=[],op=[];
  for(let i=0;i<64;i++){ip.push(k[i]^0x36);op.push(k[i]^0x5c);}
  const inner=hexToBytes(sha256Bytes(ip.concat(msgBytes)));
  return sha256Bytes(op.concat(inner));
}

const item = $input.first();
const cabecera = String((item.json.headers || {})['x-hub-signature-256'] || '');
const crudoB64 = (item.binary && item.binary.data) ? item.binary.data.data : null;

function fallo(motivo){
  return [{ json: { firma_ok: false, motivo, body: item.json.body || {} } }];
}

if (!APP_SECRET) return fallo('falta WA_APP_SECRET en el entorno de n8n');
if (!crudoB64) return fallo('no llegó el cuerpo crudo: activa "Raw Body" en el nodo Webhook');
if (!cabecera.startsWith('sha256=')) return fallo('falta la cabecera x-hub-signature-256');

const esperado = hmacSha256(utf8Bytes(APP_SECRET), b64ToBytes(crudoB64));
const recibido = cabecera.slice(7).toLowerCase();

// Comparación en tiempo constante: no filtra información por lo que tarda.
let dif = esperado.length ^ recibido.length;
for (let i = 0; i < esperado.length && i < recibido.length; i++) {
  dif |= esperado.charCodeAt(i) ^ recibido.charCodeAt(i);
}

return [{ json: {
  firma_ok: dif === 0,
  motivo: dif === 0 ? 'ok' : 'la firma no coincide con el App Secret',
  body: item.json.body || {}
} }];

// ── Normaliza el evento de WhatsApp Cloud API ─────────────────────────────
// Un solo POST puede traer VARIOS mensajes y varios cambios de estado a la
// vez. Aquí se aplana a un item por evento, con nombres de campo estables
// que no dependen del proveedor: si mañana cambia el canal, el resto del
// flujo no se entera.
//
// Regla 3 del CLAUDE.md: la identidad es cliente_id (= wa_id), nunca el
//   teléfono formateado ni el LID.
// Regla 4: campo canal en todo, para convivir con Evolution durante la
//   migración.

// Nuestro número sale del entorno, no está escrito en el nodo.
const NUESTRO_NUMERO = $env.WA_PHONE_NUMBER_ID || '';

const body = $json.body || {};
const salida = [];

for (const entry of (body.entry || [])) {
  for (const cambio of (entry.changes || [])) {
    const v = cambio.value || {};
    const meta = v.metadata || {};

    // Una misma app puede tener varios números colgando de la WABA.
    // Marcamos si el evento es del nuestro para poder descartar ruido
    // sin perder el registro (regla 1: guardar siempre).
    const numeroPropio = !NUESTRO_NUMERO || meta.phone_number_id === NUESTRO_NUMERO;

    // Los nombres de perfil llegan aparte, en contacts[], no dentro del mensaje.
    const perfiles = {};
    for (const c of (v.contacts || [])) {
      perfiles[c.wa_id] = (c.profile || {}).name || '';
    }

    for (const m of (v.messages || [])) {
      const adjunto = m[m.type] || {};
      const ref = m.referral || {};
      salida.push({ json: {
        canal:           'whatsapp_cloud',
        tipo_evento:     'mensaje',
        direccion:       'entrante',
        cliente_id:      m.from,
        wa_message_id:   m.id,
        nombre_wa:       perfiles[m.from] || '',
        tipo:            m.type,
        texto:           m.text ? m.text.body : (adjunto.caption || ''),
        media_id:        adjunto.id || null,
        media_mime:      adjunto.mime_type || null,
        respuesta_a:     (m.context || {}).id || null,
        timestamp:       new Date(Number(m.timestamp) * 1000).toISOString(),
        phone_number_id: meta.phone_number_id || '',
        display_phone:   meta.display_phone_number || '',
        numero_propio:   numeroPropio,
        // Atribución de anuncios click-to-WhatsApp: esto alimenta el CAPI.
        // Solo viene en el PRIMER mensaje. Si se pierde aquí, se pierde
        // para siempre y el pedido queda sin atribuir.
        ctwa_clid:       ref.ctwa_clid || '',
        ad_id:           ref.source_id || '',
        ad_titulo:       ref.headline || '',
        crudo:           m
      }});
    }

    for (const s of (v.statuses || [])) {
      salida.push({ json: {
        canal:           'whatsapp_cloud',
        tipo_evento:     'estado',
        direccion:       'saliente',
        cliente_id:      s.recipient_id,
        wa_message_id:   s.id,
        estado:          s.status,
        timestamp:       new Date(Number(s.timestamp) * 1000).toISOString(),
        phone_number_id: meta.phone_number_id || '',
        numero_propio:   numeroPropio,
        crudo:           s
      }});
    }

    for (const e of (v.errors || [])) {
      salida.push({ json: {
        canal:       'whatsapp_cloud',
        tipo_evento: 'error',
        codigo:      e.code,
        mensaje:     e.title || e.message || '',
        crudo:       e
      }});
    }
  }
}

// Nunca devolvemos vacío: un evento sin reconocer también es información
// y queremos verlo en el historial de ejecuciones.
if (!salida.length) {
  return [{ json: { canal: 'whatsapp_cloud', tipo_evento: 'sin_reconocer', crudo: body } }];
}
return salida;

// Fila para la tabla mensajes.
// Los valores de estado/direccion/autor/tipo estan limitados por CHECK
// constraints; estos son los que el esquema acepta (comprobado contra la
// tabla real, no de memoria):
//   estado    : enviado | entregado | leido | pendiente   (NO existe 'recibido')
//   direccion : in | out
//   autor     : cliente | bot | humano | sistema

const ev = $('Normalizar evento').item.json;

return [{ json: {
  cliente_id:   ev.cliente_id,          // wa_id: la identidad (regla 3)
  canal:        'whatsapp_cloud',       // regla 4
  direccion:    'in',
  autor:        'cliente',
  tipo:         ev.tipo,
  texto:        ev.texto || null,
  estado:       'entregado',   // nos ha llegado
  msg_id_canal: ev.wa_message_id,
  payload:      ev.crudo || null,
  creado:       ev.timestamp,
} }];

// Meta manda sent/delivered/read/failed. El CHECK de la tabla solo
// admite enviado|entregado|leido|pendiente: 'failed' NO tiene destino.
// En vez de tragarnoslo, lo marcamos y se ve en el flujo.
const MAPA = { sent: 'enviado', delivered: 'entregado', read: 'leido' };
const ev = $json;
const equivalente = MAPA[ev.estado] || null;
return [{ json: {
  wa_message_id: ev.wa_message_id,
  estado_meta:   ev.estado,
  estado_supabase: equivalente,
  mapeable:      equivalente !== null,
} }];

// El insert de PostgREST puede devolver un array o un objeto segun el
// Prefer que lleve. Normalizamos aqui para no depender de eso, y caemos
// al evento normalizado si la respuesta no trae lo que esperamos.
const ev = $('Normalizar evento').first().json;
const r = $json;
const fila = Array.isArray(r) ? r[0] : r;

return [{ json: {
  cliente_id:    (fila && fila.cliente_id)   || ev.cliente_id,
  wa_message_id: (fila && fila.msg_id_canal) || ev.wa_message_id,
  texto:         ev.texto,
  nombre_wa:     ev.nombre_wa,
  ctwa_clid:     ev.ctwa_clid,
  ad_id:         ev.ad_id,
} }];

// Convierte la respuesta del GET en un booleano que el IF no pueda
// malinterpretar, y deja escrito POR QUE vale lo que vale.
const r = $json || {};
const codigo = r.statusCode || 0;

// Si el Content-Type no fuera application/json, n8n deja el cuerpo como
// cadena. Lo parseamos por si acaso en vez de fallar en silencio.
let cuerpo = r.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) {} }

let bot_activo, motivo, fila = null;

if (codigo < 200 || codigo >= 300) {
  // Supabase no contesto bien. Seguimos atendiendo, pero queda por escrito.
  bot_activo = true;
  motivo = 'no se pudo leer el estado (http ' + codigo + '), por defecto atiende el bot';
} else if (!Array.isArray(cuerpo)) {
  bot_activo = true;
  motivo = 'respuesta inesperada (' + (typeof cuerpo) + '), por defecto atiende el bot';
} else if (cuerpo.length === 0) {
  // Cliente nuevo: nunca estuvo pausado. true es la respuesta correcta,
  // no un valor por defecto.
  bot_activo = true;
  motivo = 'cliente nuevo, sin fila en conversaciones';
} else if (cuerpo.length > 1) {
  // Imposible mientras exista el UNIQUE conversaciones_cliente_id_key,
  // pero si alguien lo quita NO queremos despertar a un cliente pausado.
  bot_activo = false;
  motivo = 'identidad duplicada: ' + cuerpo.length + ' filas para este cliente_id, no respondo';
} else {
  fila = cuerpo[0];
  if (typeof fila.bot_activo === 'boolean') {
    bot_activo = fila.bot_activo;
    motivo = bot_activo ? 'el bot atiende' : 'pausado: hay un humano al mando';
  } else {
    // La fila existe pero no trae el booleano: callar antes que equivocarse.
    bot_activo = false;
    motivo = 'la fila no trae bot_activo booleano (' + (typeof fila.bot_activo) + ')';
  }
}

const d = $('Datos del mensaje guardado').first().json;
return [{ json: Object.assign({}, d, {
  bot_activo,
  motivo_estado: motivo,
  producto_activo: (fila && fila.producto_activo) || null,
  nombre_conversacion: (fila && fila.nombre) || null,
}) }];

// ADAPTADOR. Emite los mismos nombres de campo que usaba
// "Variables + Interruptor" del v3, para que los nodos trasplantados
// funcionen sin tocarles la logica por dentro.
//
// Diferencia de fondo: la identidad ya no se saca del payload crudo
// (senderPn / remoteJid / LID), sale de cliente_id. Regla 3.

const e = $('Interpretar estado').first().json;
const n = $('Normalizar evento').first().json;
let fichas = '';
try { fichas = String($json.fichas || ''); } catch (err) {}

return [{ json: {
  numero_cliente: e.cliente_id,
  telefono_real:  e.cliente_id,   // ya no hay LID que resolver
  texto_cliente:  e.texto || '',
  nombre_cliente: e.nombre_wa || e.nombre_conversacion || '',
  mensaje_id:     e.wa_message_id,
  ctwa_clid:      e.ctwa_clid || '',
  ad_id:          e.ad_id || '',
  ad_titulo:      n.ad_titulo || '',
  ad_cuerpo:      '',
  fichas,
  producto_activo: e.producto_activo || null,
} }];

// Mismo contrato de salida que el "Leer contexto" del v3: { texto }.
// Asi "Añadir contexto" se trasplanta sin tocar una linea.
const r = $json || {};
let cuerpo = r.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) {} }
const fila = Array.isArray(cuerpo) && cuerpo.length ? cuerpo[0] : null;
return [{ json: { texto: (fila && fila.texto) || '' } }];

